//! Forwarded winmm exports. isaac-ng.exe, OpenAL32.dll and EOSSDK-Win32-Shipping.dll all import from winmm.dll and
//! get this DLL, so every winmm export is a stub (generated by build.rs) jumping to the system DLL.

use std::sync::atomic::{AtomicUsize, Ordering};

use crate::win;

include!(concat!(env!("OUT_DIR"), "/exports.rs"));

/// Fills the stub targets from the system winmm.dll. Returns the names it lacks, or `None` when it can't be loaded.
pub fn load_real() -> Option<Vec<&'static str>> {
    let mut path = [0u16; 260];
    let len = unsafe { win::GetSystemDirectoryW(path.as_mut_ptr(), path.len() as u32) } as usize;
    if len == 0 || len >= path.len() {
        return None;
    }
    let mut full: Vec<u16> = path[..len].to_vec();
    full.extend("\\winmm.dll\0".encode_utf16());
    let real = unsafe { win::LoadLibraryW(full.as_ptr()) };
    if real.is_null() {
        return None;
    }
    let mut missing = Vec::new();
    for (name, target) in NAMES.iter().zip(&TARGETS) {
        let address = unsafe { win::GetProcAddress(real, name.as_ptr()) } as usize;
        target.store(address, Ordering::SeqCst);
        if address == 0 {
            missing.push(name.trim_end_matches('\0'));
        }
    }
    Some(missing)
}
